insert into s_fifth values
('cmr81p6fx00231y08oynn7b2y','["Topical corticosteroids", "Oral antihistamines", "Systemic corticosteroids", "Calcineurin inhibitors"]'::jsonb,'["Topical antifungal cream", "Oral antihistamines", "Systemic corticosteroids", "Calcineurin inhibitors", "Topical corticosteroids"]'::jsonb,'Topical corticosteroids','Topical corticosteroids','E',md5('A 30-year-old man presents to the clinic with a rash on his hands and forearms that developed after he started using a new detergent. The rash is erythematous, itchy, and has vesicular lesions. He denies any systemic symptoms. On examination, there is localized erythema and vesicles on the affected areas.'),'A 30-year-old man presents to the clinic with a rash on his hands and forearms that developed after he started using a new detergent. The rash is erythematous, itchy, and has vesicular lesions. He denies any systemic symptoms. On examination, there is localized erythema and vesicles on the affected areas.',md5('What is the most appropriate pharmacotherapy?'),'What is the most appropriate pharmacotherapy?',md5('The correct answer is topical corticosteroids, which are the first-line treatment for localized contact dermatitis. They help reduce inflammation and itching in the affected areas. 
